package com.aitherapist.dls.catalog

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Character clip index (Story 2.3), generated by tools/art/export_clips.py into assets/character/index.json.
 * Paths are relative to the assets root. Kotlin never names a clip or step; it lists what the index says.
 */
@Serializable
data class CharacterIndex(val variants: List<CharacterVariant>)

@Serializable
data class CharacterVariant(val id: String, val reactions: List<ReactionClip>, val tasks: List<StepClipTask>)

/** A looping transparent reaction clip; its still is the first frame of [file]. */
@Serializable
data class ReactionClip(val state: String, val file: String)

@Serializable
data class StepClipTask(val id: String, val steps: List<StepClip>)

/** A step's demonstration segment (plays once) or, when [clip] is null, a still frame only. */
@Serializable
data class StepClip(val id: String, val clip: String? = null, val still: String)

object CharacterAssets {
    const val INDEX_PATH = "character/index.json"

    private val json = Json { ignoreUnknownKeys = false }

    fun decode(text: String): CharacterIndex = json.decodeFromString(CharacterIndex.serializer(), text)

    /** Every asset file the index references, for presence checks. */
    fun files(index: CharacterIndex): List<String> = index.variants.flatMap { v ->
        v.reactions.map { it.file } + v.tasks.flatMap { t -> t.steps.flatMap { listOfNotNull(it.clip, it.still) } }
    }
}
